    -45deg,
    rgba(255, 255, 255, 0.2) 0%,
    rgba(255, 0, 80, 0.7) 60%,
    rgba(100, 0, 20, 0.9) 100%
  );
}
.table {
  background-image: radial-gradient(
    circle at center,
    rgba(255, 255, 255, 0.5) 0%,
    rgba(255, 20, 50, 0.6) 50%,
    rgba(150, 0, 30, 0.8) 100%
